  const handleGrade = async () => {
    if (!answer.trim() || !isAvailable) return;
    setIsGrading(true);
    setError(null);

    try {
      const result = await gradeExamAnswer({ title, content }, answer);
      if (result) {
        setFeedback(result);
      } else {
        setError("Could not grade the answer. Please try again.");
      }
    } catch (err) {
      setError(getFriendlyErrorMessage(err));
    } finally {
      setIsGrading(false);
